\9\9\"foo\",\
\9\9\"bar\",\
\9\9\"baz\",\
\9\9\"qux\"\
\9}, function(value, index)\
\9\9return Promise.delay(1):andThen(function()\
\9\9print((\"%d) Got %s!\"):format(index, value))\
\9\9end)\
\9end)\
